INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(57541158, 'Marincess Sleepy Maiden', '海晶少女 眠鳢闺女', '海晶乙女スリーピーメイデン', 'Effect Monster', 'Cyberse', 'WATER', 5, 500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张「海晶少女」卡为对象才能发动。这张卡从手卡特殊召唤，这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，作为对象的卡不会被对方的效果破坏。 ②：把墓地的这张卡除外，以自己场上1只「海晶少女」连接怪兽为对象才能发动。从自己墓地选1只「海晶少女」连接怪兽当作装备卡使用给作为对象的怪兽装备。'),
(80627281, 'Marincess Snow', '海晶少女雪花', '海晶乙女雪花', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的「海晶少女」连接怪兽被战斗·效果破坏的场合，以那1只怪兽为对象才能发动。连接标记数量比那只怪兽少的1只「海晶少女」连接怪兽当作连接召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽只要在自己场上存在，不受对方的效果影响。'),
(21057444, 'Marincess Springirl', '海晶少女 蓝宝女孩', '海晶乙女スプリンガール', 'Effect Monster', 'Cyberse', 'WATER', 4, 1200, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1只「海晶少女」怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡作为水属性连接怪兽的连接素材送去墓地的场合才能发动。把自己场上的「海晶少女」怪兽数量的卡从自己卡组上面送去墓地。这个效果让「海晶少女」卡被送去墓地的场合，再给与对方那些「海晶少女」卡数量×200伤害。'),
(52945066, 'Marincess Wave', '海晶少女波动', '海晶乙女波動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有连接3以上的「海晶少女」怪兽存在的场合，这张卡的发动从手卡也能用。 ①：自己场上有「海晶少女」连接怪兽存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。自己场上有连接2以上的「海晶少女」怪兽存在的场合，再让自己场上的全部表侧表示怪兽直到回合结束时不受对方的效果影响。'),
(94207108, 'Marincess Wonder Heart', '海晶少女 奇迹心', '海晶乙女ワンダーハート', 'Link Monster', 'Cyberse', 'WATER', NULL, 2400, NULL, '水属性怪兽2只以上 ①：这张卡和怪兽进行战斗的伤害计算时才能发动1次。选给这张卡装备的1张自己的「海晶少女」怪兽卡特殊召唤。这张卡不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成0。这个效果特殊召唤的怪兽在结束阶段当作装备卡使用给这张卡装备。 ②：这张卡被对方破坏的场合才能发动。从自己墓地选1只连接3以下的「海晶少女」怪兽特殊召唤。'),
(29929832, 'Marine Beast', '海兽鱼', 'マリン・ビースト', 'Fusion Monster', 'Fish', 'WATER', 5, 1700, 1600, '「水之魔导师」＋「大肚海蛇」'),
(87514539, 'Marionette Mite', '傀儡虫', '傀儡虫', 'Effect Monster', 'Insect', 'DARK', 3, 1000, 1000, '①：把这张卡从手卡丢弃去墓地，以对方场上1只恶魔族·不死族怪兽为对象才能发动。那只恶魔族·不死族怪兽的控制权直到结束阶段得到。'),
(45247637, 'Mark of the Rose', '蔷薇之刻印', '薔薇の刻印', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '从自己墓地把1只植物族怪兽除外，以对方场上1只表侧表示怪兽为对象才能把这张卡发动。 ①：得到装备怪兽的控制权。 ②：自己结束阶段发动。这张卡的①的效果直到下次的自己准备阶段无效。'),
(48737767, 'Marmiting Captain', '妥善料理的队长', '切り盛り隊長', 'Effect Monster', 'Warrior', 'EARTH', 3, 1200, 400, '①：这张卡召唤成功时才能发动。让1张手卡回到卡组洗切。那之后，自己从卡组抽1张。那张抽到的卡是怪兽的场合，可以把那只怪兽特殊召唤。'),
(63881033, 'Marshalling Field', '盾徽配列场', 'マーシャリング・フィールド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己不是机械族怪兽不能特殊召唤。 ②：1回合1次，宣言5～9的任意等级才能发动。自己场上的全部5星以上的机械族怪兽变成宣言的等级。 ③：自己场上的机械族超量怪兽被破坏的场合，可以作为代替把这张卡送去墓地。 ④：这张卡从场上送去墓地的场合才能发动。从自己的卡组·墓地选1张「升阶魔法-紧急型混沌之力」加入手卡。'),
(93749093, 'Marshmacaron', '马卡龙棉花糖', 'マシュマカロン', 'Effect Monster', 'Fairy', 'LIGHT', 1, 200, 200, '这个卡名的效果1回合只能使用1次。 ①：这张卡被战斗·效果破坏的场合才能发动。从自己的手卡·卡组·墓地选这张卡以外的最多2只「马卡龙棉花糖」特殊召唤。'),
(31305911, 'Marshmallon', '棉花糖', 'マシュマロン', 'Effect Monster', 'Fairy', 'LIGHT', 3, 300, 500, '①：这张卡不会被战斗破坏。 ②：里侧表示的这张卡被攻击的伤害计算后发动。给与攻击的玩家1000伤害。'),
(66865880, 'Marshmallon Glasses', '棉花糖的眼镜', 'マシュマロンのメガネ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要自己的怪兽卡区域上有「棉花糖」存在，对方不能选择「棉花糖」以外作为攻击对象。'),
(10966439, 'Marshmao☆Yummy', '棉花喵☆黯蜜', 'マシュマオ☆ヤミー', 'Effect Monster', 'Beast', 'LIGHT', 1, 800, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有兽族·光属性怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从自己墓地把1张「味美喵」魔法·陷阱卡加入手卡。同调怪兽的效果特殊召唤的场合，也能作为代替把自己的卡组·除外状态的1张「味美喵」场地魔法卡或「味美喵」永续魔法·永续陷阱卡在自己场上表侧表示放置。'),
(81846453, 'Martial Metal Marcher', '武力军奏', '武力の軍奏', 'Synchro Tuner Monster', 'Machine', 'WIND', 3, 500, 2200, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合，以自己墓地1只调整为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡为同调素材的同调怪兽当作调整使用。'),
(71466592, 'Maryokutai', '魔力吸收球体', '魔力吸収球体', 'Effect Monster', 'Aqua', 'WATER', 3, 900, 900, '对方把魔法卡发动时，可以把自己场上表侧表示存在的这张卡解放，那个发动无效并破坏。这个效果在对方回合才能发动。'),
(44287299, 'Masaki the Legendary Swordsman', '传说之剑豪 MASAKI', '伝説の剣豪 MASAKI', 'Normal Monster', 'Warrior', 'EARTH', 4, 1100, 1100, '据说是完成了百人斩的传说中的剑豪。'),
(21143940, 'Mask Change', '假面变换', 'マスク・チェンジ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「英雄」怪兽为对象才能发动。把那只怪兽的属性确认，送去墓地。这个效果让那只怪兽从场上离开的场合，再把持有相同属性的1只「假面英雄」怪兽从额外卡组特殊召唤。'),
(93600443, 'Mask Change II', '假面变换二型', 'マスク・チェンジ・セカンド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「假面变化二型」在1回合只能发动1张。 ①：丢弃1张手卡，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽送去墓地，比那只怪兽等级高并相同属性的1只「假面英雄」怪兽当作「假面变化」的特殊召唤从额外卡组特殊召唤。'),
(87819421, 'Mask Charge', '假面补给', 'マスク・チャージ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「英雄」怪兽和1张「变化」速攻魔法卡为对象才能发动。那些卡加入手卡。'),
(82432018, 'Mask of Brutality', '凶暴化之假面', '凶暴化の仮面', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升1000，守备力下降1000。每次的自己的准备阶段支付1000分维持。不支付维持这张卡破坏。'),
(28933734, 'Mask of Darkness', '暗之假面', '闇の仮面', 'Flip Effect Monster', 'Fiend', 'DARK', 2, 900, 400, '①：这张卡反转的场合，以自己墓地1张陷阱卡为对象发动。那张卡加入手卡。'),
(20765952, 'Mask of Dispel', '魔力无力化之假面', '魔力無力化の仮面', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '选1张场上的表侧表示的魔法卡。被选的魔法卡的控制者在自己的每次准备阶段受到500分的伤害。指定的卡的场上不存在的时候，这张卡破坏。'),
(29549364, 'Mask of Restrict', '活祭品封印之假面', '生贄封じの仮面', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方不能把卡解放。'),
(56948373, 'Mask of the Accursed', '咒魂之假面', '呪魂の仮面', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这张卡装备的怪兽不能攻击。装备怪兽的控制者在自己的每次的准备阶段受到500分的伤害。'),
(57882509, 'Mask of Weakness', '弱体化之假面', '弱体化の仮面', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以1只攻击怪兽为对象才能发动。那只攻击怪兽的攻击力直到回合结束时下降700。'),
(48948935, 'Masked Beast Des Gardius', '假面魔兽 死亡护法师', '仮面魔獣デス・ガーディウス', 'Effect Monster', 'Fiend', 'DARK', 8, 3300, 2500, '这张卡不能通常召唤。把包含「假面咒术师 诅咒之喉」「梅尔基多四面兽」之内任意种的自己场上2只怪兽解放的场合可以特殊召唤。 ①：这张卡从场上送去墓地的场合，以对方场上1只表侧表示怪兽为对象发动。从卡组把1张「遗言之假面」当作装备卡使用给作为对象的怪兽装备。'),
(53573406, 'Masked Chameleon', '假面变色龙', 'カメンレオン', 'Tuner Monster', 'Reptile', 'EARTH', 4, 1600, 1100, '这张卡在自己场上没有5星以上的怪兽存在的场合才能召唤。这张卡的效果发动的回合，自己不用从额外卡组的特殊召唤以及这张卡的效果不能特殊召唤。 ①：这张卡召唤成功时，以自己墓地1只守备力0的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(87350908, 'Masked Chopper', '假面斩杀者', 'マスクド・チョッパー', 'Effect Monster', 'Fiend', 'EARTH', 1, 100, 100, '这张卡战斗破坏对方怪兽的场合，给与对方基本分2000分伤害。'),
(77581312, 'Masked Clown', '假面道化', '仮面道化', 'Normal Monster', 'Warrior', 'DARK', 2, 500, 700, '一边跳着死亡的舞蹈、一边用手上的镰刀切碎敌人的战士。'),
(39191307, 'Masked Dragon', '假面龙', '仮面竜', 'Effect Monster', 'Dragon', 'FIRE', 3, 1400, 1100, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的龙族怪兽特殊召唤。'),
(29095552, 'Masked HERO Acid', '假面－英雄 酸水', 'M・HERO アシッド', 'Fusion Monster', 'Warrior', 'WATER', 8, 2600, 2100, '这张卡用「假面变化」的效果才能特殊召唤。 ①：这张卡特殊召唤的场合发动。对方场上的魔法·陷阱卡全部破坏，对方场上的全部怪兽的攻击力下降300。'),
(59642500, 'Masked HERO Anki', '假面－英雄 暗鬼', 'M・HERO 闇鬼', 'Fusion Monster', 'Warrior', 'DARK', 8, 2800, 1200, '这张卡用「假面变化」的效果才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡可以直接攻击。那次直接攻击给与对方的战斗伤害变成一半。 ②：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1张「变化」速攻魔法卡加入手卡。'),
(85672957, 'Masked HERO Atomic', '假面－英雄 原子', 'M・HERO アトミック', 'Fusion Monster', 'Warrior', 'FIRE', 8, 2600, 2000, '这张卡用「假面变化」的效果才能特殊召唤。这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以炎属性以外的自己的墓地·除外状态的1只「假面英雄」怪兽为对象才能发动。那只怪兽无视召唤条件守备表示特殊召唤。 ②：这张卡1回合只有1次不会被战斗·效果破坏。 ③：自己结束阶段，以自己墓地1张「变化」速攻魔法卡为对象才能发动。那张卡在自己场上盖放。'),
(89870349, 'Masked HERO Blast', '假面－英雄 暴风', 'M・HERO ブラスト', 'Fusion Monster', 'Warrior', 'WIND', 6, 2200, 1800, '这张卡用「假面变化」的效果才能特殊召唤。 ①：这张卡特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成一半。 ②：自己·对方回合1次，支付500基本分，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡回到手卡。'),
(58481572, 'Masked HERO Dark Law', '假面－英雄 暗法', 'M・HERO ダーク・ロウ', 'Fusion Monster', 'Warrior', 'DARK', 6, 2400, 1800, '这张卡用「假面变化」的效果才能特殊召唤。 ①：只要这张卡在怪兽区域存在，被送去对方墓地的卡不去墓地而除外。 ②：1回合1次，对方在抽卡阶段以外从卡组把卡加入手卡的场合才能发动。对方手卡随机1张除外。'),
(62624486, 'Masked HERO Dian', '假面－英雄 晶钻', 'M・HERO ダイアン', 'Fusion Monster', 'Warrior', 'EARTH', 8, 2800, 3000, '这张卡用「假面变化」的效果才能特殊召唤。 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。从卡组把1只4星以下的「英雄」怪兽特殊召唤。'),
(22093873, 'Masked HERO Divine Wind', '假面－英雄 神风', 'M・HERO カミカゼ', 'Fusion Monster', 'Warrior', 'WIND', 8, 2700, 1900, '这张卡用「假面变化」的效果才能特殊召唤。 ①：这张卡不会被战斗破坏。 ②：只要这张卡在怪兽区域存在，对方在同1次的战斗阶段中只能用1只怪兽攻击。 ③：这张卡战斗破坏对方怪兽送去墓地时才能发动。自己抽1张。'),
(10808715, 'Masked HERO Dusk Crow', '假面－英雄 暮鸦', 'M・HERO ダスク・クロウ', 'Effect Monster', 'Warrior', 'DARK', 4, 1200, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从自己墓地把1只「英雄」怪兽除外才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把「假面英雄 暮鸦」以外的1只「假面英雄」怪兽加入手卡。'),
(66206748, 'Masked HERO Fountain', '假面－英雄 喷泉', 'M・HERO ファウンティン', 'Effect Monster', 'Warrior', 'WATER', 4, 1000, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从手卡把1只「英雄」怪兽守备表示特殊召唤。 ②：这张卡为让卡的效果发动而被送去墓地的场合或者被效果送去墓地的场合才能发动。从自己的卡组·墓地把1张「假面变化」在自己场上盖放。'),
(58288218, 'Masked HERO Furnace', '假面－英雄 焰炉', 'M・HERO ファーネス', 'Effect Monster', 'Warrior', 'FIRE', 7, 2200, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不是「英雄」怪兽不能从额外卡组特殊召唤）。从卡组把1张「假面变化」或「融合」加入手卡。那之后，选自己1张手卡丢弃。 ②：自己把炎属性以外的「英雄」融合怪兽特殊召唤的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(58147549, 'Masked HERO Goka', '假面－英雄 刚火', 'M・HERO 剛火', 'Fusion Monster', 'Warrior', 'FIRE', 6, 2200, 1800, '这张卡用「假面变化」的效果才能特殊召唤。这张卡的攻击力上升自己墓地存在的名字带有「英雄」的怪兽数量×100的数值。'),
(50608164, 'Masked HERO Koga', '假面－英雄 光牙', 'M・HERO 光牙', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 2500, 1800, '这张卡用「假面变化」的效果才能特殊召唤。 ①：这张卡的攻击力上升对方场上的怪兽数量×500。 ②：1回合1次，把自己墓地1只「英雄」怪兽除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降因为这个效果发动而除外的怪兽的攻击力数值。这个效果在对方回合也能发动。'),
(10920352, 'Masked HERO Vapor', '假面－英雄 蒸汽', 'M・HERO ヴェイパー', 'Fusion Monster', 'Warrior', 'WATER', 6, 2400, 2000, '这张卡用「假面变化」的效果才能特殊召唤。这张卡不会被魔法·陷阱·效果怪兽的效果破坏。'),
(22512406, 'Masked Ninja Ebisu', '覆面忍者 惠比寿', '覆面忍者ヱビス', 'Effect Monster', 'Warrior', 'WIND', 4, 1200, 1800, '1回合1次，自己场上有「覆面忍者 惠比寿」以外的名字带有「忍者」的怪兽存在的场合才能发动。自己场上的名字带有「忍者」的怪兽数量的对方魔法·陷阱卡回到持有者手卡。这个效果适用的回合，自己场上的「忍者义贼 五卫五卫」可以直接攻击对方玩家。'),
(10189126, 'Masked Sorcerer', '假面魔道士', '仮面魔道士', 'Effect Monster', 'Spellcaster', 'DARK', 4, 900, 1400, '这张卡造成对方玩家基本分伤害的时候，自己抽1张卡。'),
(6855503, 'Masquerade the Blazing Dragon', '赫灼龙 伪装魔种', '赫灼竜マスカレイド', 'Fusion Monster', 'Fiend', 'DARK', 8, 2500, 2000, '「死狱乡」怪兽＋光·暗属性怪兽 这个卡名的②的效果1回合只能使用1次。 ①：只要融合召唤的这张卡在怪兽区域存在，对方若不支付600基本分，则不能把卡的效果发动。 ②：自己·对方回合，这张卡在墓地存在，对方场上有仪式·融合·同调·超量·连接怪兽的其中任意种存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(34906152, 'Mass Driver', '质量加速器', 'マスドライバー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每祭掉自己场上1只怪兽，给与对方基本分400分的伤害。'),
(21768554, 'Mass Hypnosis', '集团催眠', '集団催眠', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「外星」的怪兽存在时才能发动。选择对方场上存在的最多3只放置有A指示物的怪兽得到控制权。这张卡在发动回合的结束阶段时破坏。'),
(67820935, 'Massivemorph', '肥大化', '肥大化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力变成2倍，不能直接攻击。'),
(75499502, 'Master & Expert', '主人与能手', 'マスター・アン・エキスパート', 'Normal Monster', 'Beast', 'EARTH', 4, 1200, 1000, '怪兽使高手、忠心于主人的怪兽。组合起来相当完美。'),
(25727454, 'Master Craftsman Gamil', '名匠 加米尔', '名匠 ガミル', 'Effect Monster', 'Pyro', 'FIRE', 2, 200, 200, '①：自己怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只怪兽的攻击力直到回合结束时上升300。'),
(16191953, 'Master Gig', '吉格大王', 'マスター・ジーグ', 'Effect Monster', 'Psychic', 'EARTH', 8, 2600, 1400, '支付1000基本分发动。把自己场上表侧表示存在的念动力族怪兽数量的对方场上存在的怪兽破坏。这个效果1回合只能使用1次。'),
(55794644, 'Master Hyperion', '主宰者·许珀里翁', 'マスター・ヒュペリオン', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2700, 2100, '①：这张卡可以把自己的手卡·场上·墓地1只「代行者」怪兽除外，从手卡特殊召唤。 ②：1回合1次，从自己墓地把1只天使族·光属性怪兽除外，以场上1张卡为对象才能发动。那张卡破坏。场上有「天空的圣域」存在的场合，这个效果1回合可以使用最多2次。'),
(24530661, 'Master Kyonshee', '达人僵尸', '達人キョンシー', 'Normal Monster', 'Zombie', 'EARTH', 4, 1750, 1000, '一直在寻找强大对方的僵尸。传说是一个武术高手。'),
(49814180, 'Master Monk', '武僧大师', 'マスターモンク', 'Effect Monster', 'Rock', 'EARTH', 5, 1900, 1000, '这张卡不能通常召唤。把自己场上存在的1只「武僧战士」做祭品的场合才能特殊召唤。这张卡1回合可以攻击2次。'),
(85059922, 'Master of Chaos', '超魔导战士－混沌之主宰者', '超魔導戦士－マスター・オブ・カオス', 'Fusion Monster', 'Spellcaster', 'DARK', 8, 3000, 2500, '「黑魔术师」＋「混沌」仪式怪兽 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，以自己墓地1只光·暗属性怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把自己场上的光·暗属性怪兽各1只解放才能发动。对方场上的怪兽全部除外。 ③：融合召唤的这张卡被战斗·效果破坏的场合，以自己墓地1张魔法卡为对象才能发动。那张卡加入手卡。'),
(9551692, 'Master of Ham', 'HAM之主', 'マスター・オブ・HAM', 'Fusion Monster', 'Beast', 'EARTH', 5, 2100, 1850, '兽族怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤·反转的场合才能发动。从自己的手卡·卡组把1只反转怪兽里侧守备表示特殊召唤。 ②：这张卡在墓地存在的场合，从自己的场上（表侧表示）·墓地把2只反转怪兽除外才能发动。这张卡里侧守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(27134689, 'Master of Oz', 'OZ之主', 'マスター・オブ・OZ', 'Fusion Monster', 'Beast', 'EARTH', 9, 4200, 3700, '「巨大树熊」＋「死亡袋鼠」'),
(34160055, 'Master of the Flaming Dragonswords', '使龙炎剑的高手', '龍炎剣の使い手', 'Effect Monster', 'Warrior', 'FIRE', 4, 1800, 1200, '自己场上有「使龙炎剑的高手」以外的怪兽召唤时，可以把那只怪兽的等级上升1星，这张卡的攻击力直到结束阶段时上升300。'),
(34079868, 'Master Peace, the True Dracoslayer', '真龙剑士 卓辉星·拼图', '真竜剣士マスターP', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2950, 2950, '这张卡不能通常召唤。把自己场上的「龙剑士」怪兽和「龙魔王」怪兽各1只解放的场合才能特殊召唤。 ①：1回合1次，魔法·陷阱·怪兽的效果发动时才能发动。那个发动无效并破坏。 ②：场上的这张卡被对方破坏的场合才能发动。从卡组把「龙剑士」怪兽和「龙魔王」怪兽各1只特殊召唤。'),
(21377582, 'Master Peace, the True Dracoslaying King', '真龙剑皇 至尊行者 完灵', '真竜剣皇マスターP', 'Effect Monster', 'Wyrm', 'LIGHT', 8, 2950, 2950, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。 ①：这张卡不受和为这张卡的上级召唤而解放的卡的原本种类（怪兽·魔法·陷阱）相同种类的效果影响。 ②：这张卡是已上级召唤的场合，自己·对方回合1次，从自己墓地把1张永续魔法·永续陷阱卡除外，以场上1张其他卡为对象才能发动。那张卡破坏。'),
(12800564, 'Master Peace, the True Dracoverlord', '真龙魔王 至尊行者 完灵', '真竜魔王マスターP', 'Effect Monster', 'Wyrm', 'DARK', 10, 2950, 2950, '这张卡通常召唤的场合，必须把自己场上3只怪兽解放作召唤，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡是已上级召唤的场合，对方把手卡·场上的怪兽的效果发动时才能发动。那个发动无效并破坏。 ②：上级召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。下次的对方主要阶段跳过。'),
(75195825, 'Master Pendulum, the Dracoslayer', '龙剑士 至尊行者 灵摆', '竜剣士マスターP', 'Pendulum Normal Monster', 'Dragon', 'LIGHT', 4, 1950, NULL, '得到志同道合之士们的力量后「龙剑士 光辉星·灵摆」成长的模样。他是被施过不明神秘诅咒后显现出类似龙魔族的龙之力，但在此之前的记忆全部丢失了，真相因此不明。他相信“龙化秘法”就是解开那诅咒和记忆的关键，今天仍旧继续着前去讨伐邪恶魔王的旅程。'),
(34541543, 'Master Tao the Chanter', '大阴阳师 道', '大陰陽師 タオ', 'Effect Monster', 'Illusion', 'EARTH', 3, 1200, 900, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ②：这张卡被送去墓地的场合，以「大阴阳师 道」以外的自己墓地1只幻想魔族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是幻想魔族怪兽不能从墓地特殊召唤。'),
(45644898, 'Master with Eyes of Blue', '青之眼祭司', '青き眼の祭司', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, 300, 1200, '「青色眼睛的祭司」的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1只光属性·1星调整为对象才能发动。那只怪兽加入手卡。 ②：让墓地的这张卡回到卡组，以自己场上1只效果怪兽为对象才能发动。那只怪兽送去墓地，从自己墓地选那只怪兽以外的1只「青眼」怪兽特殊召唤。'),
(11327848, 'Master''s Diploman', '修士号 文凭人', '修士号ディプロマン', 'Effect Monster', 'Machine', 'DARK', 5, 2000, 2000, '①：这张卡上级召唤成功的场合，以自己墓地1只怪兽和对方场上1只表侧表示怪兽为对象才能发动。那只墓地的怪兽当作装备卡使用给那只对方怪兽装备。只要这个效果把怪兽装备中，装备怪兽的攻击力下降那个攻击力数值。 ②：只要这张卡在怪兽区域存在，有自己的魔法与陷阱区域的装备卡装备的对方怪兽的效果不能发动。'),
(63101468, 'Masterflare Hyperion', '耀斑主宰者·许珀里翁', 'マスターフレア・ヒュペリオン', 'Synchro Monster', 'Fairy', 'LIGHT', 10, 3200, 2600, '调整＋调整以外的天使族怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把1只「代行者」怪兽或者1只有「天空的圣域」的卡名记述的怪兽从手卡·卡组·额外卡组送去墓地才能发动。直到结束阶段，这张卡当作和那只怪兽同名卡使用，得到相同效果。 ②：对方把卡的效果发动时，从自己的手卡·墓地把1只天使族怪兽除外，以场上1张卡为对象才能发动。那张卡除外。'),
(35606858, 'Masterking Archfiend', '长世国王恶魔', 'パーペチュアルキングデーモン', 'Link Monster', 'Fiend', 'DARK', NULL, 2000, NULL, '恶魔族怪兽2只 这张卡的控制者在每次自己准备阶段支付500基本分。或者不支付让这张卡破坏。这张卡的①②的效果在同一连锁上各能发动1次。 ①：自己把基本分支付的场合才能发动。和那个数值相同的攻击力或守备力的1只恶魔族怪兽从卡组送去墓地。 ②：恶魔族怪兽被送去自己墓地的场合才能发动。掷1次骰子，那之内的1只受出现的数目的效果适用。 ●1：加入手卡。 ●2～5：回到卡组。 ●6：特殊召唤。'),
(22609617, 'Mataza the Zapper', '奇袭的又佐', '不意打ち又佐', 'Effect Monster', 'Warrior', 'DARK', 3, 1300, 800, '这张卡在同1个战斗阶段中可以进行2次攻击。这张卡在场上以表侧表示存在时，控制权不能被变更。'),
(94446564, 'Matching Outfits', '情侣装', 'ペア・ルック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方卡组最上面的卡给双方确认，那些卡是相同种类（怪兽·魔法·陷阱）的场合，双方把那些卡加入手卡。不是的场合，双方把那些卡除外。'),
(17008760, 'Materiactor Annulus', '原物质之圆环炉', '原質の円環炉', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上1个超量素材取除。取除的超量素材被送去自己墓地的场合，可以再把那张卡在自己场上盖放。'),
(64767757, 'Materiactor Critical', '原物质之突破临界', '原質の臨界超過', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：怪兽的效果·魔法·陷阱卡发动时才能发动。自己场上的「原质炉」超量怪兽作为超量素材中的1张自己的卡加入手卡，那个发动无效。那之后，加入手卡的卡种类的以下效果适用。 ●怪兽：选自己1张手卡回到卡组最下面。 ●魔法：自己场上的「原质炉」超量怪兽的攻击力上升1000。 ●陷阱：可以把这个效果加入手卡的卡在自己场上盖放。'),
(72409226, 'Materiactor Exagard', '原物质・艾可萨世界蛇', 'マテリアクトル・エクサガルド', 'XYZ Monster', 'Dragon', 'WATER', 3, 2000, 2000, '3星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1只「原质炉」怪兽特殊召唤或把1张「原质炉」魔法·陷阱卡加入手卡。 ②：对方把怪兽召唤·特殊召唤的场合才能发动。这张卡作为超量素材中的包含「原质炉」卡的最多2张卡加入手卡。自己墓地有通常怪兽存在的场合，可以再让场上1张卡回到手卡。'),
(37426272, 'Materiactor Exareptor', '原物质・艾可萨环蜥', 'マテリアクトル・エクサレプト', 'Effect Monster', 'Dragon', 'WATER', 3, 1500, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看，从手卡丢弃1张其他卡才能发动。丢弃的卡以外的1只3星通常怪兽从自己的卡组·墓地加入手卡。那之后，可以把这张卡守备表示特殊召唤。 ②：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只3阶超量怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1500。'),
(70597485, 'Materiactor Gigaboros', '原物质・吉伽衔尾蛇', 'マテリアクトル・ギガヴォロス', 'XYZ Monster', 'Dragon', 'DARK', 3, 500, 500, '3星怪兽×2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力·守备力上升自己手卡数量×500。 ②：把这张卡1个超量素材取除才能发动。从卡组选1只「原质炉」怪兽在这张卡下面重叠作为超量素材。 ③：对方的主要阶段以及战斗阶段才能发动。这张卡作为超量素材中的1张卡加入持有者手卡。'),
(33008376, 'Materiactor Gigadra', '原物质・吉伽环龙', 'マテリアクトル・ギガドラ', 'Effect Monster', 'Dragon', 'DARK', 3, 1000, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是超量怪兽不能从额外卡组特殊召唤。 ②：丢弃1张手卡才能发动。从手卡·卡组把1只3星通常怪兽特殊召唤。把通常怪兽丢弃发动的场合，可以把特殊召唤的怪兽改成1只「原质炉」怪兽。'),
(38669664, 'Materiactor Meltdown', '原物质之炉芯熔毁', '原質の炉心溶融', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从自己卡组上面把6张卡翻开，可以从那之中选1张「原质炉」卡加入手卡。剩余用喜欢的顺序回到卡组上面。那之后，可以把自己场上的3阶超量怪兽作为超量素材中的1张卡加入手卡。 ②：自己的超量怪兽把效果发动的场合才能发动。把自己卡组最上面的卡作为自己场上1只「原质炉」超量怪兽的超量素材。'),
(66059345, 'Materiactor Meltthrough', '原物质之炉芯贯穿', '原質の炉心貫通', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，从自己卡组上面把6张卡翻开，用喜欢的顺序回到卡组上面。 ②：1回合1次，支付1500基本分才能发动。把1只「原质炉」超量怪兽在自己场上1只3星通常怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个回合，自己不是超量怪兽不能从额外卡组特殊召唤。 ③：超量怪兽超量召唤的场合才能发动。把自己卡组最上面的卡作为自己场上1只「原质炉」超量怪兽的超量素材。'),
(64911387, 'Materiactor Zeptwing', '原物质・仄普托环禽', 'マテリアクトル・ゼプトウィング', 'Effect Monster', 'Dragon', 'FIRE', 3, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「原质炉」卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤·反转的场合才能发动。从卡组把「原质炉仄普托翼鸟」以外的1张「原质炉」卡加入手卡。那之后，可以从自己墓地把1只3星通常怪兽加入手卡或特殊召唤。'),
(24649931, 'Materialization', '变幻', '変幻', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以以自己或对方的魔法与陷阱区域1张表侧表示的怪兽卡为对象，从以下效果选择1个发动。 ●作为对象的卡在原本持有者的场上特殊召唤。 ●作为对象的卡回到手卡。 ●作为对象的卡破坏。那之后，可以把持有那张卡的等级以下的等级的场上1只怪兽破坏。'),
(41386308, 'Mathematician', '数学家', 'マスマティシャン', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1500, 500, '①：这张卡召唤成功时才能发动。从卡组把1只4星以下的怪兽送去墓地。 ②：这张卡被战斗破坏送去墓地时才能发动。自己从卡组抽1张。'),
(80965043, 'Mathmech Addition', '斩机加伐', '斬機アディオン', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1000, 1000, '这个卡名的效果1回合只能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽的攻击力直到回合结束时上升1000。这个效果特殊召唤的回合，这张卡不能攻击。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能从额外卡组特殊召唤。'),
(41410651, 'Mathmech Billionblade Nayuta', '斩机刀那由他', '斬機刀ナユタ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '电子界族怪兽才能装备。这个卡名的①②的效果1回合各能使用1次。 ①：装备怪兽和对方怪兽进行战斗的伤害计算时，从卡组把1只「斩机」怪兽送去墓地才能发动。装备怪兽的攻击力直到回合结束时上升送去墓地的怪兽的攻击力数值。 ②：这张卡从魔法与陷阱区域送去墓地的场合，以「斩机刀 那由他」以外的自己墓地1张「斩机」卡为对象才能发动。那张卡加入手卡。'),
(36521307, 'Mathmech Circular', '斩机弓形', '斬機サーキュラー', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把「斩机 圆武」以外的1只「斩机」怪兽送去墓地才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己只能用1只怪兽攻击。 ②：这张卡在怪兽区域存在的状态，自己场上有「斩机」怪兽召唤·特殊召唤的场合才能发动。从卡组把1张「斩机」魔法·陷阱卡加入手卡。'),
(17946349, 'Mathmech Diameter', '斩机直径', '斬機ダイア', 'Tuner Monster', 'Cyberse', 'LIGHT', 4, 1000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤时，以自己墓地1只电子界族·4星怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果不能发动。 ②：场上的这张卡为素材作同调·超量召唤的「斩机」怪兽得到以下效果。 ●这张卡特殊召唤的回合1次，对方把魔法·陷阱·怪兽的效果发动时才能发动。那个效果无效。'),
(89743495, 'Mathmech Division', '斩机除伐', '斬機ディヴィジョン', 'Effect Monster', 'Cyberse', 'EARTH', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：把额外怪兽区域1只自己的电子界族怪兽解放才能发动。从手卡以及自己墓地各选最多1只电子界族·4星怪兽特殊召唤。 ②：这张卡被送去墓地的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成一半。'),
(14025912, 'Mathmech Equation', '斩机方程式', '斬機方程式', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「斩机」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力直到回合结束时上升1000。'),
(14393464, 'Mathmech Induction', '斩机归纳法', '斬機帰納法', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的电子界族怪兽的攻击力上升500。 ②：自己场上有「斩机」怪兽存在的场合，把魔法与陷阱区域的表侧表示的这张卡送去墓地，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(52354896, 'Mathmech Multiplication', '斩机乘伐', '斬機マルチプライヤー', 'Effect Monster', 'Cyberse', 'EARTH', 4, 500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只电子界族·4星怪兽为对象才能发动。那只怪兽的等级直到回合结束时变成8星。 ②：这张卡被送去墓地的场合，以额外怪兽区域1只自己的电子界族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成2倍。'),
(53577438, 'Mathmech Nabla', '斩机纳布拉', '斬機ナブラ', 'Tuner Monster', 'Cyberse', 'DARK', 4, 1000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只电子界族怪兽解放才能发动。从卡组把1只「斩机」怪兽特殊召唤。 ②：这张卡被送去墓地的场合，以额外怪兽区域1只自己的电子界族怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(27182739, 'Mathmech Sigma', '斩机西格玛', '斬機シグマ', 'Tuner Monster', 'Cyberse', 'LIGHT', 4, 1000, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，额外怪兽区域没有自己怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能从额外卡组特殊召唤。 ②：把自己场上的这张卡作为「斩机」同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。'),
(16360142, 'Mathmech Subtraction', '斩机减伐', '斬機サブトラ', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1000, 1000, '这个卡名的效果1回合只能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽的攻击力直到回合结束时下降1000。这个效果特殊召唤的回合，这张卡不能攻击。这个效果的发动后，直到回合结束时自己不是电子界族怪兽不能从额外卡组特殊召唤。'),
(87804365, 'Mathmech Superfactorial', '斩机超阶乘', '斬機超階乗', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以以自己墓地最多3只「斩机」怪兽为对象，从以下效果选择1个发动（同名卡最多1张）。 ●那些怪兽效果无效特殊召唤，只用那些怪兽为素材把1只「斩机」同调怪兽同调召唤。那个时候的同调素材怪兽不去墓地回到持有者卡组。 ●那些怪兽效果无效特殊召唤，只用那些怪兽为素材把1只「斩机」超量怪兽超量召唤。'),
(52904476, 'Matriarch of Nephthys', '奈芙蒂斯的参悟者', 'ネフティスの悟り手', 'Effect Monster', 'Spellcaster', 'WIND', 2, 600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：以「奈芙提斯之悟道者」以外的自己墓地1只4星以下的「奈芙提斯」怪兽为对象才能发动。选1张手卡破坏，作为对象的怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡被效果破坏送去墓地的场合，下次的自己准备阶段才能发动。这张卡从墓地特殊召唤。'),
(92650749, 'Mature Chronicle', '成熟编年史', 'マチュア・クロニクル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：每次「于贝尔」怪兽或者有「于贝尔」的卡名记述的怪兽特殊召唤，给这张卡放置1个年代记指示物。 ②：可以把自己场上的年代记指示物的以下数量取除，那个效果发动。 ●1：从自己墓地把1只「于贝尔」特殊召唤。 ●2：自己的除外状态的1张卡加入手卡。 ●3：从卡组选1张卡除外。 ●4：场上1张卡破坏。 ●5：从卡组把1张「超融合」加入手卡。'),
(80921533, 'Mausoleum of the Emperor', '死皇帝的陵墓', '死皇帝の陵墓', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：双方玩家在自己主要阶段可以从以下效果选择1个发动。 ●支付1000基本分才能发动。不用解放来进行需要1只解放的手卡1只怪兽的通常召唤。 ●支付2000基本分才能发动。不用解放来进行需要2只解放的手卡1只怪兽的通常召唤。'),
(24382602, 'Mausoleum of White', '光之灵堂', '光の霊堂', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只光属性·1星调整召唤。 ②：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。从手卡·卡组把1只通常怪兽送去墓地，作为对象的怪兽的攻击力·守备力直到回合结束时上升送去墓地的怪兽的等级×100。 ③：把墓地的这张卡除外才能发动。从卡组把1张「毁灭之爆裂疾风弹」加入手卡。'),
(59036972, 'Mavelus', '奇迹鸟', 'マブラス', 'Fusion Monster', 'Winged Beast', 'WIND', 4, 1300, 900, '「大炮鸟」＋「邪炎之翼」'),
(89812483, 'Max Metalmorph', '钢铁化・强化反射装甲', 'メタル化・強化反射装甲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示怪兽解放才能把这张卡发动。把有「金属化·强化反射装甲」的卡名记述的1只不能通常召唤的怪兽从自己的手卡·卡组·墓地特殊召唤。那之后，可以把这张卡当作持有以下效果的装备卡使用给那只怪兽装备。 ●装备怪兽攻击力·守备力上升400，不会被魔法·怪兽的效果破坏，对方不能把装备怪兽作为魔法·怪兽的效果的对象。'),
(94538053, 'Max Warrior', '最高战士', 'マックス・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 4, 1800, 800, '这张卡向对方怪兽攻击的场合，伤害步骤内攻击力上升400。这张卡战斗破坏对方怪兽的场合，直到下次的自己的准备阶段时这张卡的等级变成2星，原本的攻击力·守备力成为一半数值。'),
(30707994, 'Maximum Six', '最大值六', 'マキシマム・シックス', 'Effect Monster', 'Warrior', 'EARTH', 6, 1900, 1600, '这张卡祭品召唤成功时，丢1个骰子。只要这张卡在场上表侧表示存在，这张卡的攻击力上升丢出骰子数×200的攻击力。'),
(23434538, 'Maxx "C"', '增殖的Z', '増殖するG', 'Effect Monster', 'Insect', 'EARTH', 2, 500, 200, '这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，把这张卡从手卡送去墓地才能发动。这个回合中，以下效果适用。 ●每次对方把怪兽特殊召唤，自己抽1张。'),
(41867019, 'Mayakashi Mayhem', '魔妖游行', '魔妖遊行', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果在同一连锁上只能发动1次。 ①：从额外卡组以外有不死族同调怪兽特殊召唤的场合才能发动（伤害步骤也能发动）。从以下效果选1个适用。这个回合，自己的「魔妖游行」的效果不能有相同效果适用。 ●自己从卡组抽1张。 ●从卡组选「魔妖游行」以外的1张「魔妖」魔法·陷阱卡在自己场上盖放。 ●对方场上1只攻击力最低的怪兽送去墓地。 ●给与对方800伤害。'),
(39753577, 'Mayakashi Metamorphosis', '魔妖变生', '魔妖変生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。 ①：丢弃1张手卡，从自己墓地的怪兽以及除外的自己怪兽之中以1只「魔妖」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不会成为对方的效果的对象。'),
(2364438, 'Mayakashi Return', '魔妖回天', '魔妖廻天', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选「魔妖回天」以外的1张「魔妖」卡加入手卡或送去墓地。'),
(51225407, 'Mayakashi Winter', '魔妖坏劫', '魔妖壊劫', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：对方场上的怪兽的攻击力·守备力下降自己墓地的「魔妖」怪兽种类×100。 ②：把自己场上的表侧表示的1只「魔妖」怪兽和这张卡送去墓地才能发动。自己从卡组抽1张。 ③：从自己墓地把这张卡和1只不死族怪兽除外，以自己墓地1只「魔妖」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(91405870, 'Mayhem Fur Hire', '烈风的空牙团', '烈風の空牙団', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「空牙团」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(93368494, 'Mayosenju Daibak', '魔妖仙兽 大刃祸是', '魔妖仙獣 大刃禍是', 'Pendulum Effect Monster', 'Beast', 'WIND', 10, 3000, 300, '这张卡不用灵摆召唤不能特殊召唤。 ①：这张卡的灵摆召唤不会被无效化。 ②：这张卡召唤·特殊召唤成功的场合，以场上最多2张卡为对象才能发动。那些卡回到持有者手卡。 ③：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(21364070, 'Mayosenju Hitot', '魔妖仙兽 独眼群主', '魔妖仙獣 独眼群主', 'Pendulum Effect Monster', 'Beast', 'WIND', 10, 2000, 3000, '这张卡不用灵摆召唤不能特殊召唤。 ①：这张卡召唤·特殊召唤成功的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。 ②：这张卡在怪兽区域存在，每次自己的卡的效果让这张卡以外的场上的卡回到手卡·卡组发动。自己场上的全部「妖仙兽」怪兽的攻击力上升500。 ③：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(6133894, 'Mazera DeVille', '大魔王 魔杰拉', 'デビルマゼラ', 'Effect Monster', 'Fiend', 'DARK', 8, 2800, 2300, '这张卡不能进行通常召唤。这张卡仅当场上存在「万魔殿-恶魔的巢窟-」时，祭掉自己场上1只以表侧表示存在的「杰拉的战士」才能特殊召唤。这张卡特殊召唤成功时，对方随机丢弃3张手卡。此效果仅当自己场上存在「万魔殿-恶魔的巢窟-」时才适用。'),
(50176820, 'Mech Bass', '电子鱼', 'サイボーグ・バス', 'Normal Monster', 'Machine', 'WATER', 5, 1800, 1500, '以背后附着的炮台发射闪光粒子加农炮。'),
(63545455, 'Mech Mole Zombie', '僵尸鬼灯', 'ゾンビランプ', 'Normal Monster', 'Zombie', 'DARK', 2, 500, 400, '把手腕像火箭一样发射攻击的不死怪兽。'),
(10110717, 'Mecha Bunny', '机械兔', 'メカウサー', 'Effect Monster', 'Machine', 'EARTH', 2, 800, 100, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只「机械兔」在自己场上里侧守备表示特殊召唤。这张卡反转时，选择场上存在的1张卡，给与那个控制者500分伤害。'),
(16943770, 'Mecha Phantom Beast Aerosguin', '幻兽机 航空飞鸟', '幻獣機エアロスバード', 'Effect Monster', 'Machine', 'WIND', 3, 1600, 400, '①：1回合1次，把「幻兽机 航空飞鸟」以外的自己墓地1只「幻兽机」怪兽除外才能发动。在自己场上把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。 ②：这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。 ③：只要自己场上有衍生物存在，这张卡不会被战斗·效果破坏。'),
(44097050, 'Mecha Phantom Beast Auroradon', '幻兽机 曙光女神百头龙', '幻獣機アウローラドン', 'Link Monster', 'Machine', 'WIND', NULL, 2100, NULL, '机械族怪兽2只以上 ①：这张卡连接召唤成功的场合才能发动。在自己场上把3只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这个回合，自己不能连接召唤。 ②：1回合1次，把自己场上最多3只怪兽解放才能发动。解放的怪兽数量的以下效果适用。 ●1只：选场上1张卡破坏。 ●2只：从卡组把1只「幻兽机」怪兽特殊召唤。 ●3只：从自己墓地选1张陷阱卡加入手卡。'),
(4417407, 'Mecha Phantom Beast Blackfalcon', '幻兽机 黑猎鹰', '幻獣機ブラックファルコン', 'Effect Monster', 'Machine', 'WIND', 4, 1200, 1700, '这张卡攻击宣言时，把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，1回合1次，把1只衍生物解放才能发动。选择对方场上1只怪兽变成表侧守备表示。这个效果在对方回合也能发动。'),
(67489919, 'Mecha Phantom Beast Blue Impala', '幻兽机 蓝冲高角羚', '幻獣機ブルーインパラス', 'Tuner Monster', 'Machine', 'WIND', 3, 1400, 1100, '把这张卡作为同调素材的场合，不是机械族怪兽的同调召唤不能使用，其他的同调素材怪兽必须是自己的手卡·场上的名字带有「幻兽机」的怪兽。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，对方场上有怪兽存在，自己场上没有怪兽存在的场合，把墓地的这张卡从游戏中除外才能发动。把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。'),
(94973028, 'Mecha Phantom Beast Coltwing', '幻兽机 倾翼小马', '幻獣機コルトウィング', 'Effect Monster', 'Machine', 'WIND', 4, 1600, 1500, '①：自己场上有其他的「幻兽机」怪兽存在，这张卡特殊召唤成功的场合发动。在自己场上把2只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。 ②：这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。 ③：只要自己场上有衍生物存在，这张卡不会被战斗·效果破坏。 ④：1回合1次，把自己场上2只衍生物解放，以对方场上1张卡为对象才能发动。那张对方的卡破坏并除外。'),
(53451824, 'Mecha Phantom Beast Concoruda', '幻兽机 协和金翅鸟', '幻獣機コンコルーダ', 'Synchro Monster', 'Machine', 'WIND', 7, 2400, 1200, '调整＋调整以外的怪兽1只以上 只要这张卡在场上表侧表示存在，自己场上的衍生物不会被战斗以及效果破坏。场上的这张卡被对方破坏送去墓地的场合，把自己场上的衍生物全部解放才能发动。从自己墓地选择1只4星以下的名字带有「幻兽机」的怪兽特殊召唤。'),
(22110647, 'Mecha Phantom Beast Dracossack', '幻兽机 哥萨克龙', '幻獣機ドラゴサック', 'XYZ Monster', 'Machine', 'WIND', 7, 2600, 2200, '7星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。在自己场上把2只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。 ②：只要自己场上有衍生物存在，这张卡不会被战斗·效果破坏。 ③：1回合1次，把自己场上1只「幻兽机」怪兽解放，以场上1张卡为对象才能发动。那张卡破坏。这个效果发动的回合，这张卡不能攻击。'),
(66200210, 'Mecha Phantom Beast Hamstrat', '幻兽机 同温层仓鼠', '幻獣機ハムストラット', 'Effect Monster', 'Machine', 'WIND', 3, 1100, 1600, '这张卡反转时，把2只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，把1只衍生物解放才能发动。选择自己墓地1只名字带有「幻兽机」的怪兽特殊召唤。「幻兽机 同温层仓鼠」的这个效果1回合只能使用1次。'),
(20368763, 'Mecha Phantom Beast Harrliard', '幻兽机 鹞式狮豹兽', '幻獣機ハリアード', 'Effect Monster', 'Machine', 'WIND', 4, 1800, 800, '1回合1次，为让这张卡以外的卡的效果发动而让自己场上的怪兽被解放时，把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，1回合1次，把1只衍生物解放才能发动。从手卡把1只名字带有「幻兽机」的怪兽特殊召唤。'),
(26949946, 'Mecha Phantom Beast Jaculuslan', '幻兽机 鲁斯兰枪蛇', '幻獣機ヤクルスラーン', 'Synchro Monster', 'Machine', 'WIND', 9, 2700, 2000, '「幻兽机」调整＋调整以外的「幻兽机」怪兽1只以上 ①：这张卡同调召唤成功时，把自己场上的「幻兽机衍生物」任意数量解放才能发动。对方手卡随机选解放的数量丢弃。 ②：只要这张卡在怪兽区域存在，这张卡以外的自己场上的「幻兽机」怪兽不会被战斗·效果破坏。 ③：这张卡被对方破坏的场合才能发动。从卡组选1张速攻魔法卡在自己的魔法与陷阱区域盖放。'),
(41329458, 'Mecha Phantom Beast Kalgriffin', '幻兽机 加里宁狮鹫', '幻獣機グリーフィン', 'Effect Monster', 'Machine', 'WIND', 7, 1000, 2500, '自己的主要阶段时，把自己场上2只名字带有「幻兽机」的怪兽解放才能发动。这张卡从手卡特殊召唤。「幻兽机 加里宁狮鹫」的这个效果1回合只能使用1次。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，1回合1次，把手卡1只名字带有「幻兽机」的怪兽丢弃才能发动。把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。'),
(31533704, 'Mecha Phantom Beast Megaraptor', '幻兽机 猛禽大盗龙', '幻獣機メガラプター', 'Effect Monster', 'Machine', 'WIND', 4, 1900, 1000, '自己场上有衍生物特殊召唤时，把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。「幻兽机 猛禽大盗龙」的这个效果1回合只能使用1次。这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，1回合1次，把1只衍生物解放才能发动。从卡组把1只名字带有「幻兽机」的怪兽加入手卡。'),
(72291078, 'Mecha Phantom Beast O-Lion', '幻兽机 猎户雄狮', '幻獣機オライオン', 'Tuner Monster', 'Machine', 'WIND', 2, 600, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有衍生物存在，这张卡不会被战斗·效果破坏。 ②：这张卡被送去墓地的场合才能发动。在自己场上把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。 ③：把墓地的这张卡除外才能发动。进行手卡1只「幻兽机」怪兽的召唤。'),
(44026393, 'Mecha Phantom Beast Raiten', '幻兽机 雷电貂', '幻獣機ライテン', 'Effect Monster', 'Machine', 'WIND', 4, 1500, 1500, '①：丢弃1张手卡才能发动。在自己场上把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这个效果的发动后，直到回合结束时自己不是「幻兽机」怪兽不能作为融合·同调·超量·连接召唤的素材。 ②：这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。 ③：只要自己场上有衍生物存在，这张卡不会被战斗·效果破坏。'),
(15335853, 'Mecha Phantom Beast Sabre Hawk', '幻兽机 全球剑齿虎', '幻獣機サーバルホーク', 'Effect Monster', 'Machine', 'WIND', 4, 2100, 100, '这张卡不能直接攻击。自己墓地有名字带有「幻兽机」的怪兽以外的怪兽存在的场合，这张卡不能攻击。这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，1回合1次，把1只衍生物解放才能发动。选择自己或者对方的墓地1张卡从游戏中除外。'),
(30811116, 'Mecha Phantom Beast Stealthray', '幻兽机 长尾隐形鳐', '幻獣機レイステイルス', 'Effect Monster', 'Machine', 'WIND', 3, 100, 2100, '这张卡给与对方基本分战斗伤害时，把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，1回合1次，把1只衍生物解放才能发动。选择场上1张魔法·陷阱卡破坏。'),
(67922702, 'Mecha Phantom Beast Tetherwolf', '幻兽机 拴绳飞狼', '幻獣機テザーウルフ', 'Effect Monster', 'Machine', 'WIND', 4, 1700, 1200, '①：这张卡召唤成功的场合发动。在自己场上把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。 ②：这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。 ③：只要自己场上有衍生物存在，这张卡不会被战斗·效果破坏。 ④：这张卡和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前1次，把自己场上1只衍生物解放才能发动。这张卡的攻击力直到回合结束时上升800。'),
(904186, 'Mecha Phantom Beast Token', '垂直着陆', '垂直着陸', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(76902476, 'Mecha Phantom Beast Turtletracer', '幻兽机 追踪海龟', '幻獣機タートレーサー', 'Effect Monster', 'Machine', 'WIND', 3, 500, 2000, '这张卡的等级上升自己场上的「幻兽机衍生物」的等级的合计数值。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，只要这张卡在场上表侧表示存在，1回合1次，自己场上的「幻兽机衍生物」不会被战斗破坏。'),
(31480215, 'Mecha Phantom Beast Warbluran', '幻兽机 暴风雪莺', '幻獣機ウォーブラン', 'Tuner Monster', 'Machine', 'WIND', 1, 300, 300, '这张卡作为机械族怪兽的同调召唤的素材送去墓地的场合，把1只「幻兽机衍生物」（机械族·风·3星·攻/守0）特殊召唤。这个效果适用过的回合，自己不能把风属性以外的怪兽特殊召唤。只要自己场上有衍生物存在，这张卡不会被战斗以及效果破坏。此外，把自己场上1只名字带有「幻兽机」的怪兽解放才能发动。这张卡的等级上升1星。「幻兽机 暴风雪莺」的效果1回合只能发动1次。'),
(40160226, 'Mecha Sea Dragon Plesion', '机海龙 蛇颈龙', '機海竜プレシオン', 'Effect Monster', 'Machine', 'WATER', 5, 2300, 1800, '自己场上有海龙族怪兽存在的场合，这张卡可以不用解放作召唤。1回合1次，可以通过把自己场上1只水属性怪兽解放，选择对方场上表侧表示存在的1张卡破坏。'),
(94667532, 'Mecha-Dog Marron', '机械犬 小栗子', '機械犬マロン', 'Effect Monster', 'Machine', 'LIGHT', 4, 1000, 1000, '场上的这张卡被战斗破坏送去墓地时，给与双方基本分1000分的伤害。场上的这张卡因为战斗以外的方式的破坏送去墓地时，给与对方基本分1000分的伤害。'),
(94412545, 'Mechaleon', '机械变色龙', 'メカレオン', 'Normal Monster', 'Reptile', 'WATER', 2, 800, 600, '变换身体颜色可以隐藏在任何地方。'),
(22512237, 'Mechanical Hound', '机械猎犬', 'メカニカル・ハウンド', 'Effect Monster', 'Machine', 'EARTH', 7, 2800, 1500, '只要自己手卡数目是0张，对方不能发动魔法卡。'),
(101303081, 'Mechanical Mechanic', NULL, NULL, 'Tuner Monster', 'Machine', 'WIND', 3, 500, 500, NULL),
(34442949, 'Mechanical Snail', '机械蜗牛', 'メカニカルスネイル', 'Normal Monster', 'Machine', 'DARK', 3, 800, 1000, '机器改造的蜗牛，但是速度却没什么变化。'),
(7359741, 'Mechanicalchaser', '机械猎手', 'メカ・ハンター', 'Normal Monster', 'Machine', 'DARK', 4, 1850, 800, '听从机械王的命令，在抓住目标前都会紧追不舍的猎捕。'),
(15914410, 'Mechquipped Angineer', '机装天使 引擎天兵', '機装天使エンジネル', 'XYZ Monster', 'Fairy', 'LIGHT', 3, 1800, 1000, '3星怪兽×2 1回合1次，把这张卡1个超量素材取除，选择自己场上表侧攻击表示存在的1只怪兽才能发动。选择的怪兽变成表侧守备表示，这个回合那只怪兽不会被战斗以及卡的效果破坏。这个效果在对方回合也能发动。'),
(76211194, 'Meda Bat', '暗黑拿破仑', 'D・ナポレオン', 'Normal Monster', 'Fiend', 'DARK', 2, 800, 400, '恶人创造的眼珠恶魔。用黑暗炸弹进行爆破攻击。'),
(84206435, 'Medallion of the Ice Barrier', '冰结界的纹章', '氷結界の紋章', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「冰结界」怪兽加入手卡。'),
(88494899, 'Medium of the Ice Barrier', '冰结界的交灵师', '氷結界の交霊師', 'Effect Monster', 'Spellcaster', 'WATER', 7, 2200, 1600, '①：对方场上的卡数量比自己场上的卡多4张以上的场合，这张卡可以从手卡特殊召唤。 ②：只要这张卡在自己的怪兽区域存在，那个期间对方1回合只能有1张魔法·陷阱卡发动。'),
(58843503, 'Medium Piece Golem', '中块石人', 'ミッド・ピース・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 4, 1600, NULL, '自己场上有「大块石人」表侧表示存在的场合这张卡召唤·反转召唤·特殊召唤成功时，可以从自己卡组把1只「小块石人」特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(97556336, 'Medius the Pure', '无垢者 墨迪乌斯', '無垢なる者 メディウス', 'Effect Monster', 'Fairy', 'DARK', 4, 1800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组选1只「狱神」怪兽加入手卡或特殊召唤。 ②：这张卡在墓地存在的场合才能发动。从自己的手卡·场上（表侧表示）让1只怪兽回到卡组，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(2694423, 'Medusa Worm', '美杜莎蠕虫', 'メデューサ・ワーム', 'Effect Monster', 'Rock', 'EARTH', 2, 500, 600, '这张卡1个回合1次可以变成里侧守备表示。这张卡反转召唤成功时，对方场上1只怪兽破坏。'),
(18551923, 'Medusa, Watcher of the Evil Eye', '咒眼之死徒 美杜莎', '呪眼の死徒 メドゥサ', 'Effect Monster', 'Fiend', 'DARK', 4, 1400, 1600, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时，以「咒眼之死徒 美杜莎」以外的自己墓地1张「咒眼」卡为对象才能发动。那张卡加入手卡。 ②：这张卡有「太阴之咒眼」装备的场合，以对方墓地1只怪兽为对象才能发动。那只怪兽除外。这个效果在对方回合也能发动。 ③：这张卡的②的效果发动的场合，下次的准备阶段发动。选自己墓地1张卡除外。'),
(46820049, 'Mefist the Infernal General', '地狱将军·墨非斯特', '地獄将軍・メフィスト', 'Effect Monster', 'Fiend', 'DARK', 5, 1800, 1700, '这张卡攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方那个数值的战斗伤害。这张卡对对方造成战斗伤害时，对方随机丢弃1张手卡。'),
(96546575, 'Mega Fortress Whale', '大要塞鲸', '大要塞クジラ', 'Effect Monster', 'Fish', 'WATER', 7, 2550, 2350, '这个卡名的①②③的效果1回合各能使用1次。 ①：场上有「海」存在的场合才能发动。这个回合，自己的水属性怪兽可以直接攻击。 ②：对方战斗阶段，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。 ③：场上的这张卡被战斗·效果破坏的场合才能发动。从自己的卡组·墓地选1只战士族·水属性怪兽加入手卡或特殊召唤。'),
(21817254, 'Mega Thunderball', '大雷电球', 'メガ・サンダーボール', 'Normal Monster', 'Thunder', 'WIND', 2, 750, 600, '在地止旋转，向周围发出电击的球。'),
(32062913, 'Mega Ton Magical Cannon', '巨型魔导加农炮', 'メガトン魔導キャノン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的10个魔力指示物取除发动。对方场上存在的卡全部破坏。'),
(29876299, 'Megalith Anastasis', '巨石异物・再生', 'メガリス・アナスタシス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：丢弃1张手卡才能发动。从卡组把4星以下和8星以上的「巨石遗物」怪兽各1只加入手卡。 ②：1回合1次，自己把「巨石遗物」怪兽仪式召唤的场合，可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己抽2张。那之后，选自己1张手卡丢弃。 ●对方场上1只怪兽解放。'),
(25726386, 'Megalith Aratron', '巨石异物・阿拉特隆', 'メガリス・アラトロン', 'Ritual Effect Monster', 'Rock', 'EARTH', 8, 2000, 3000, '「巨石遗物」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡从手卡丢弃才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「巨石遗物」仪式怪兽仪式召唤。 ②：自己场上的卡为对象的对方的效果发动时才能发动。从自己墓地选1只仪式怪兽回到卡组最下面，那个发动无效并破坏。'),
(99628747, 'Megalith Bethor', '巨石异物・贝索尔', 'メガリス・ベトール', 'Ritual Effect Monster', 'Rock', 'EARTH', 8, 1500, 2600, '「巨石遗物」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「巨石遗物」仪式怪兽仪式召唤。 ②：这张卡仪式召唤成功的场合，以最多有自己墓地的仪式怪兽种类数量的对方场上的卡为对象才能发动。那些卡破坏。'),
(76209339, 'Megalith Emergence', '巨石异物・创出', 'メガリス・エマージョン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只「巨石遗物」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合回到持有者卡组最下面。'),
(90444325, 'Megalith Hagith', '巨石异物・黑吉斯', 'メガリス・ハギト', 'Ritual Effect Monster', 'Rock', 'EARTH', 4, 1300, 2600, '「巨石遗物」卡降临。这个卡名的②的效果1回合只能使用1次。 ①：这张卡仪式召唤成功的场合才能发动。从卡组把1张「巨石遗物」魔法·陷阱卡加入手卡。 ②：自己主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含场上的这张卡的自己的手卡·场上的怪兽解放，从手卡把1只仪式怪兽仪式召唤。'),
(44293356, 'Megalith Notrah Plura', '巨石异物・阿特拉普尔隆', 'メガリス・ノートラ・プルーラ', 'Ritual Effect Monster', 'Rock', 'EARTH', 12, 3700, 2700, '「巨石遗物」卡降临 这张卡若非以只使用仪式怪兽来作的仪式召唤则不能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。这个回合，对方不能对应自己的「巨石遗物」仪式怪兽的效果的发动把效果发动。 ②：对方把卡的效果发动时才能发动。那个发动无效并破坏。这个效果把以场上的卡为对象的效果的发动无效的场合，可以再把对方场上1只怪兽解放。'),
(36849933, 'Megalith Och', '巨石异物・奥赫', 'メガリス・オク', 'Ritual Effect Monster', 'Rock', 'EARTH', 4, 1000, 2700, '「巨石遗物」卡降临。这个卡名的②的效果1回合只能使用1次。 ①：这张卡仪式召唤成功的场合才能发动。自己从卡组抽1张。那之后，选1张手卡丢弃。 ②：自己·对方的主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含场上的这张卡的自己的手卡·场上的怪兽解放，从手卡把1只仪式怪兽仪式召唤。'),
(63056220, 'Megalith Ophiel', '巨石异物・犹菲勒', 'メガリス・オフィエル', 'Ritual Effect Monster', 'Rock', 'EARTH', 4, 1600, 2500, '「巨石遗物」卡降临 这个卡名的②的效果1回合只能使用1次。 ①：这张卡仪式召唤的场合才能发动。从卡组把「巨石遗物·奥菲尔」以外的1只「巨石遗物」怪兽加入手卡。 ②：自己主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含场上的这张卡的自己的手卡·场上的怪兽解放，从手卡把1只仪式怪兽仪式召唤。'),
(63233638, 'Megalith Phaleg', '巨石异物・富雷格', 'メガリス・ファレグ', 'Ritual Effect Monster', 'Rock', 'EARTH', 8, 2500, 1200, '「巨石遗物」卡降临。这个卡名的①的效果1回合只能使用1次。 ①：把这张卡从手卡丢弃才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只「巨石遗物」仪式怪兽仪式召唤。 ②：只要这张卡在怪兽区域存在，自己场上的怪兽的攻击力·守备力上升自己墓地的仪式怪兽数量×300。'),
(78990927, 'Megalith Phul', '巨石异物・普尔', 'メガリス・フール', 'Ritual Effect Monster', 'Rock', 'EARTH', 2, 500, 2000, '「巨石遗物」卡降临 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡仪式召唤的场合，以自己墓地1只仪式怪兽为对象才能发动。这张卡的等级变成和那只怪兽相同。那之后，作为对象的怪兽加入手卡。 ②：自己·对方的主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡·卡组把1只「巨石遗物」仪式怪兽仪式召唤。'),
(8805651, 'Megalith Phuloch', '巨石异物・普赫奥尔', 'メガリス・フローチュ', 'Ritual Effect Monster', 'Rock', 'EARTH', 4, 2000, 300, '「巨石遗物」卡降临 这个卡名的②的效果1回合只能使用1次，①②的效果在同一连锁上不能发动。 ①：这张卡仪式召唤的场合才能发动。从自己墓地把1张「巨石遗物」卡加入手卡。 ②：自己·对方的主要阶段才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把包含场上的这张卡的自己的手卡·场上的怪兽解放，从自己墓地把「巨石遗物·富洛曲」以外的1只「巨石遗物」仪式怪兽仪式召唤。'),
(84504242, 'Megalith Portal', '巨石异物・传送门', 'メガリス・ポータル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：仪式召唤的怪兽在1回合各有1次不会被战斗破坏。 ②：「巨石遗物」怪兽特殊召唤的场合，以自己墓地1只仪式怪兽为对象才能发动。那只怪兽加入手卡。'),
(40204620, 'Megalith Promotion', '巨石异物・升格', 'メガリス・プロモーション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己场上1只4星以下的怪兽为对象才能发动。那只怪兽的等级直到回合结束时变成原本等级的2倍。'),
(69003792, 'Megalith Unformed', '巨石异物・无定形', 'メガリス・アンフォームド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●对方场上的全部怪兽的攻击力直到回合结束时下降场上的仪式怪兽数量×500。 ●等级合计直到变成仪式召唤的怪兽的等级的2倍为止，把自己的手卡·场上的怪兽解放，从卡组把1只「巨石遗物」仪式怪兽守备表示仪式召唤。'),
(81823360, 'Megalosmasher X', '巨型碎噬者 X', 'メガロスマッシャーX', 'Normal Monster', 'Dinosaur', 'WATER', 4, 2000, NULL, '太古汪洋大海中突然出现的恐龙型生化人。靠引以自豪的消音装甲来偷偷靠近猎物背后，然后悄无声息地咬住对方，可是因为进入捕食模式之后身体是发光样式所以经常会逃脱。'),
(22046459, 'Megamorph', '巨大化', '巨大化', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：自己基本分比对方少的场合，装备怪兽的攻击力变成原本攻击力的2倍。自己基本分比对方多的场合，装备怪兽的攻击力变成原本攻击力的一半。'),
(71544954, 'Megarock Dragon', '巨岩龙', 'メガロック・ドラゴン', 'Effect Monster', 'Rock', 'EARTH', 7, -1, -1, '这张卡不能通常召唤。把自己墓地存在的岩石族怪兽除外才能特殊召唤。这张卡的原本攻击力·守备力变成特殊召唤时所除外的岩石族怪兽数×700的数值。'),
(44139064, 'Megaroid City', '巨机人都市', 'メガロイド都市', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：以这张卡以外的自己场上1张卡为对象才能发动。那张卡破坏，从卡组把1张「机人」卡加入手卡。 ②：自己的「机人」怪兽进行战斗的伤害计算时，从卡组把1只「机人」怪兽送去墓地才能发动。那只进行战斗的自己怪兽只在那次伤害计算时原本攻击力和原本守备力交换。'),
(7562372, 'Megasonic Eye', '超音速之眼', 'メガソニック・アイ', 'Normal Monster', 'Machine', 'DARK', 5, 1500, 1800, '来自宇宙尽头的杀人机器。用不明金属制作。'),
(75390004, 'Megazowler', '巨身多角龙', 'メガザウラー', 'Normal Monster', 'Dinosaur', 'EARTH', 6, 1800, 2000, '全身长满角的恐龙。突击攻击很强烈！'),
(23032273, 'Megirus Light', '梅基拉斯之光', 'メギラス・ライト', 'Normal Monster', 'Fiend', 'DARK', 3, 900, 600, '从眼中放出恶光给予对方损伤。'),
(83035296, 'Megistric Maginician', '墨吉斯特里仪术师', 'メギストリーの儀術師', 'Effect Monster', 'Spellcaster', 'FIRE', 1, NULL, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物。 ②：自己·对方的结束阶段把这张卡3个魔力指示物取除，以除外的1张自己的魔法卡为对象才能发动。把1张那张卡的同名卡从卡组加入手卡。'),
(47731128, 'Mei-Kou, Master of Barriers', '结界术师 明孔', '結界術師 メイコウ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1700, 600, '把这张卡解放发动。场上表侧表示存在的1张永续魔法或者永续陷阱卡破坏。'),
(11825276, 'Meizen the Battle Ninja', '戎之忍者-冥禅', '戎の忍者－冥禪', 'Fusion Monster', 'Warrior', 'DARK', 6, 2500, 1500, '种族不同的「忍者」怪兽×2 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上的上记卡解放的场合可以从额外卡组特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：自己的「忍者」怪兽可以直接攻击。 ②：只要自己场上有里侧守备表示怪兽存在，这张卡不会成为攻击对象。 ③：对方把效果发动时才能发动。从卡组把1只「忍者」怪兽表侧守备表示或者里侧守备表示特殊召唤。'),
(93715853, 'Mekanikal Arkfiend', '魔神 大神机', '魔神アーク・マキナ', 'Effect Monster', 'Fiend', 'DARK', 4, 100, 2100, '①：这张卡给与对方战斗伤害时才能发动。从自己的手卡·墓地选1只通常怪兽特殊召唤。'),
(84754430, 'Mekk-Knight Avram', '机界骑士 阿布拉姆', '機界騎士アヴラム', 'Normal Monster', 'Psychic', 'LIGHT', 4, 2000, NULL, '守护星之光明的勇者　为灭除幻界于世之暗　对天选之人托付己身之力。 星之宝杯继承的意志成为崭新钥匙　化成斩绝黑暗之剑。'),
(20537097, 'Mekk-Knight Blue Sky', '苍穹之机界骑士', '蒼穹の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 5, 2000, 2500, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以从手卡往那个纵列的自己场上特殊召唤。 ②：这张卡从手卡的召唤·特殊召唤成功的场合才能发动。把和这张卡相同纵列的对方的卡数量的「苍穹之机界骑士」以外的「机界骑士」怪兽从卡组加入手卡（同名卡最多1张）。'),
(21887175, 'Mekk-Knight Crusadia Avramax', '双穹之圣骑联盟・机界骑士', '双穹の騎士アストラム', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 3000, NULL, '从额外卡组特殊召唤的怪兽2只以上 ①：只要连接召唤的这张卡在怪兽区域存在，对方怪兽不能选择其他怪兽作为攻击对象，对方不能把这张卡作为效果的对象。 ②：这张卡和特殊召唤的怪兽进行战斗的伤害计算时才能发动1次。这张卡的攻击力只在那次伤害计算时上升那只对方怪兽的攻击力数值。 ③：连接召唤的这张卡被对方送去墓地的场合才能发动。场上1张卡回到卡组。'),
(66022706, 'Mekk-Knight Green Horizon', '翠岚之机界骑士', '翠嵐の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 6, 2100, 1600, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以在那个纵列的自己场上特殊召唤。 ②：这张卡和相同纵列的对方怪兽进行战斗的攻击宣言时，以自己墓地1只「机界骑士」怪兽为对象才能发动。那只怪兽加入手卡。'),
(92204263, 'Mekk-Knight Indigo Eclipse', '绀碧之机界骑士', '紺碧の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 8, 2400, 2400, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以在那个纵列的自己场上特殊召唤。 ②：1回合1次，以自己场上1只「机界骑士」怪兽为对象才能发动。那只自己怪兽的位置向其他的自己的主要怪兽区域移动。这个效果在对方回合也能发动。'),
(72006609, 'Mekk-Knight of the Morning Star', '晨星之机界骑士', '明星の機械騎士', 'Link Monster', 'Machine', 'LIGHT', NULL, 2000, NULL, '包含「机界骑士」怪兽的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合，从手卡丢弃1只「机界骑士」怪兽或者1张「星遗物」卡才能发动。从卡组把1张「星遗物」卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己的「机界骑士」怪兽不会被和与那自身纵列不同纵列的怪兽的战斗破坏，那次战斗发生的对自己的战斗伤害变成0。'),
(93020401, 'Mekk-Knight Orange Sunset', '灯影之机界骑士', '燈影の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 6, 800, 3000, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以在那个纵列的自己场上特殊召唤。 ②：和这张卡相同纵列的对方的卡从场上离开的场合或者被战斗破坏的场合才能发动。从手卡把1只「机界骑士」怪兽特殊召唤。'),
(28692962, 'Mekk-Knight Purple Nightfall', '紫宵之机界骑士', '紫宵の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 8, 2500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以从手卡往那个纵列的自己场上特殊召唤。 ②：以自己场上1只「机界骑士」怪兽为对象才能发动。那只怪兽直到下次的自己回合的准备阶段除外，从卡组把「紫宵之机界骑士」以外的1只「机界骑士」怪兽加入手卡。这个效果在对方回合也能发动。'),
(56809158, 'Mekk-Knight Red Moon', '红莲之机界骑士', '紅蓮の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 7, 2300, 2600, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以在那个纵列的自己场上特殊召唤。 ②：从自己墓地把1只「机界骑士」怪兽除外，以和这张卡相同纵列1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(38502358, 'Mekk-Knight Spectrum Supreme', '星痕之机界骑士', '星痕の機界騎士', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 3000, NULL, '「机界骑士」怪兽2只以上 这个卡名的③的效果1回合只能使用1次。 ①：和这张卡相同纵列没有其他卡存在的场合，这张卡可以直接攻击。 ②：额外怪兽区域的这张卡的所连接区没有怪兽存在的场合，这张卡不会被效果破坏，不会成为对方的效果的对象。 ③：把和这张卡相同纵列1张其他的自己的卡送去墓地才能发动。从卡组把1只「机界骑士」怪兽守备表示特殊召唤。'),
(29415459, 'Mekk-Knight Yellow Star', '黄华之机界骑士', '黄華の機界騎士', 'Effect Monster', 'Psychic', 'LIGHT', 7, 2200, 2800, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：相同纵列有卡2张以上存在的场合，这张卡可以在那个纵列的自己场上特殊召唤。 ②：从自己墓地把1只「机界骑士」怪兽除外，以和这张卡相同纵列1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(3715284, 'Meklord Army Deployer Obbligato', '机皇兵厂 助奏', '機皇兵廠オブリガード', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。这张卡破坏，从卡组把「机皇兵厂 助奏」以外的2只「机皇兵」怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族怪兽不能特殊召唤。 ②：这张卡被送去墓地的场合才能发动。这个回合的结束阶段，给与对方为自己场上的「机皇」怪兽数量×100伤害。'),
(2137678, 'Meklord Army of Granel', '机皇兵 神陆一型', '機皇兵グランエル・アイン', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1200, '这张卡的攻击力上升这张卡以外的场上表侧表示存在的名字带有「机皇」的怪兽数量×100的数值。这张卡召唤成功时，可以选择对方场上表侧表示存在的1只怪兽，那只怪兽的攻击力直到结束阶段时变成一半。'),
(75733063, 'Meklord Army of Skiel', '机皇兵 神空一型', '機皇兵スキエル・アイン', 'Effect Monster', 'Machine', 'WIND', 4, 1200, 1000, '这张卡的攻击力上升这张卡以外的场上表侧表示存在的名字带有「机皇」的怪兽数量×200的数值。这张卡被战斗破坏送去墓地时，可以从自己卡组把1只名字带有「机皇兵」的怪兽特殊召唤。'),
(39648965, 'Meklord Army of Wisel', '机皇兵 神智一型', '機皇兵ワイゼル・アイン', 'Effect Monster', 'Machine', 'DARK', 4, 1800, NULL, '①：这张卡的攻击力上升这张卡以外的场上的「机皇」怪兽数量×100。 ②：1回合1次，这张卡以外的自己的「机皇」怪兽向守备表示怪兽攻击宣言时才能发动。那次战斗用那只自己怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(39109382, 'Meklord Assembly', '机皇创出', '機皇創出', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②③的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「机皇」怪兽加入手卡。 ②：丢弃1张手卡，以自己场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：自己场上的表侧表示的「机皇」怪兽被战斗·效果破坏的场合，以这张卡以外的场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(38522377, 'Meklord Astro Dragon Asterisk', '机皇神龙 星标', '機皇神龍アステリスク', 'Effect Monster', 'Machine', 'DARK', 10, NULL, NULL, '这张卡不能通常召唤。自己场上的「机皇」怪兽是3只以上的场合可以特殊召唤。 ①：这张卡特殊召唤成功时，以这张卡以外的自己场上的「机皇」怪兽任意数量为对象才能发动。那些自己的「机皇」怪兽送去墓地。这张卡的攻击力变成这个效果送去墓地的怪兽的原本攻击力合计数值。 ②：每次同调怪兽特殊召唤发动。给与把那些怪兽特殊召唤的玩家1000伤害。'),
(4837861, 'Meklord Astro Dragon Triskelion', '机皇神龙 三曲枝', '機皇神龍トリスケリア', 'Effect Monster', 'Machine', 'DARK', 10, 3000, NULL, '这张卡不能通常召唤。从自己墓地把「机皇」怪兽3种类各1只除外的场合可以特殊召唤。 ①：1回合1次，这张卡的攻击宣言时才能发动。把对方的额外卡组确认，选那之内的1只怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力数值。 ③：有同调怪兽装备的这张卡在同1次的战斗阶段中最多3次可以向怪兽攻击。'),
(63468625, 'Meklord Astro Mekanikle', '机皇神 机录∞', '機皇神マシニクル∞', 'Effect Monster', 'Machine', 'LIGHT', 12, 4000, 4000, '这张卡不能通常召唤。从手卡把3只「机皇」怪兽送去墓地的场合才能特殊召唤。 ①：1回合1次，以对方场上1只同调怪兽为对象才能发动。那只对方同调怪兽给这张卡装备。 ②：这个攻击力上升自身的效果装备的怪兽的攻击力数值。 ③：自己准备阶段，把自身的效果装备的1只自己怪兽送去墓地才能发动。给与对方那只怪兽的攻击力数值的伤害。这个效果发动的回合，自己不能进行战斗阶段。'),
(2992036, 'Meklord Astro the Eradicator', '根绝机皇神', '根絶の機皇神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地3只「机皇」怪兽为对象才能发动（同名卡最多1张）。那些怪兽加入手卡或无视召唤条件特殊召唤。这张卡的发动后，直到下次的自己回合的结束时自己不是机械族怪兽不能特殊召唤。 ②：自己场上有「机皇神」怪兽存在的场合，把墓地的这张卡除外才能发动。选对方场上1只同调怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(66594927, 'Meklord Deflection', '机皇统制', '機皇統制', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「机皇」怪兽为对象才能发动。那只怪兽的攻击力变成自己场上的「机皇」怪兽的原本攻击力合计数值，直到回合结束时那只怪兽的战斗发生的对对方的战斗伤害变成0。 ②：自己场上的「机皇」怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(4545683, 'Meklord Emperor Granel', '机皇帝 神陆∞', '機皇帝グランエル∞', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '这张卡不能通常召唤，用自身的效果才能特殊召唤。 ①：自己场上的表侧表示怪兽被效果破坏送去墓地时才能发动。手卡的这张卡特殊召唤。 ②：1回合1次，以对方场上1只同调怪兽为对象才能发动。那只对方同调怪兽给这张卡装备。 ③：这个攻击力·守备力上升自己基本分一半数值，攻击力上升自身的效果装备的怪兽的攻击力数值。 ④：以自身的效果装备的1只怪兽为对象才能发动。那只守备表示特殊召唤。');